import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def check_property(n):
    """Checks if k^2 == 1 (mod n) for all k coprime to n, 1 <= k < n."""
    if n < 2:
        return False

    for k in range(1, n):
        if gcd(k, n) == 1:
            if (k * k - 1) % n != 0:
                # print(f"Failed for n={n} with k={k}. k^2-1 = {k*k - 1}, which is not divisible by {n}")
                return False
    return True

n_values = list(range(2, 16))
satisfying_n = []

for n in n_values:
    if check_property(n):
        satisfying_n.append(n)

print(f"N values that satisfy the condition up to 15: {satisfying_n}")

import math

N = [2, 3, 4, 6, 8, 12, 24]
results = {}

def check_condition(n):
    """Checks if k^2 == 1 mod n for all k coprime to n."""
    if n == 1:
        return True # Though n >= 2 is required

    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check k^2 = 1 mod n
            if (k * k) % n != 1:
                return False
    return True

print("Verification Results for N = {2, 3, 4, 6, 8, 12, 24}:")
for n in N:
    is_satisfied = check_condition(n)
    results[n] = is_satisfied
    print(f"n={n}: {'Satisfies' if is_satisfied else 'FAILS'}")

print("\n--- Structured Results ---")
for n, satisfied in results.items():
    print(f"n={n}: {satisfied}")
